clc; clearvars;

root_dir = "C:\Users\tely1\PhD";

addpath(genpath(fullfile(root_dir, "O3_Lidar\")));

% DIAL Processing Functions
% addpath(genpath(fullfile(root_dir, "O3_Lidar\proc_functions")));

% Signal Analysis and Modeling Functions
addpath(genpath(fullfile(root_dir, "signal_analysis\")));
%%
start_day       = datetime(datetime("2024-10-01", "InputFormat", "uuuu-MM-dd"), "InputFormat", "uuuu-MM-dd"); %[control:datePicker:8a9f]{"position":[28,79]}
end_day         = datetime(datetime("2024-10-31", "InputFormat", "uuuu-MM-dd"), "InputFormat", "uuuu-MM-dd"); %[control:datePicker:4f06]{"position":[28,79]}
data_path       = fullfile(root_dir, "lidar_data");
result_path     = fullfile(root_dir, "O3_processed_data");
log_path        = fullfile(root_dir, "O3_processed_data");

log_file        = fullfile(log_path, "o3_process.log");
aerosol         = [];

if ~exist(result_path, "dir")
    mkdir(result_path)
end

if ~exist(log_path, "dir")
    mkdir(log_path)
end

if ~exist(log_file, "file")
    fid = fopen(log_file, "a");
    if fid ~= -1
        fclose(fid);
    end
end

folders = dir(data_path);
folders = folders([folders.isdir]);

for i = 1:size(folders, 1) %[output:group:5d039cb0]
    tmp_folder = folders(i).name;

    try
        folderDate = datetime(tmp_folder, "InputFormat", "uuuuMMdd", "Format", "uuuuMMdd");
    catch
        continue
    end

    if folderDate >= start_day && folderDate <= end_day
        fprintf("processing %s\n", tmp_folder); %[output:21123c24]
        output_filename = sprintf("o3_processed_%04d%02d%02d.mat", year(folderDate), month(folderDate), day(folderDate));

        try
            out = process(fullfile(data_path, tmp_folder), fullfile(result_path, output_filename), aerosol);
        catch ME
            warning("Processing failed for %s: %s", tmp_folder, ME.message);

            fid = fopen(log_file, "a");
            if fid ~= -1
                fprintf(fid, "%s | %s | %s | %s\n", char(datetime("now", "Format", "yyyy-MM-dd HH:mm:ss")), tmp_folder, "FAILED", ME.message);
                fclose(fid);
            end
        end
    end
end %[output:group:5d039cb0]
%%
plt = "pc"; %[control:dropdown:11a3]{"position":[7,11]}
switch plt
    case "an"
        q_nr_plt    = out.q_o3_an_nr;
        q_fr_plt    = out.q_o3_an_fr;
        q_merge_plt = out.q_o3_an_merged;
    case "pc"
        q_nr_plt    = out.q_o3_pc_nr;
        q_fr_plt    = out.q_o3_pc_fr;
        q_merge_plt = out.q_o3_pc_merged;
    case "mg"
        q_nr_plt    = out.q_o3_mg_nr;
        q_fr_plt    = out.q_o3_mg_fr;
        q_merge_plt = out.q_o3_mg_merged;
end

times_avg = out.times_avg;
z_km_vec = out.z_vec.*1e-3;

ND_plot(times_avg,z_km_vec,q_nr_plt,[0 120],[0 5],"Ozone Mixing Ratio NR","Altitude (km)", "ppb", "",12) %[output:4590bb62]
ND_plot(times_avg,z_km_vec,q_fr_plt,[0 120],[0 10],"Ozone Mixing Ratio FR","Altitude (km)", "ppb", "",12) %[output:4e477d19]
ND_plot(times_avg,z_km_vec,q_merge_plt,[0 120],[0 10],"Ozone Mixing Ratio FR-NR Merge","Altitude (km)", "ppb", "",12) %[output:766655ee]
%%\ Uncertainty profiles
n_profiles = length(out.times_avg);
profile_id = 1; %[control:slider:a903]{"position":[14,15]}
uncertainty_range = "merged"; %[control:dropdown:a904]{"position":[21,29]}

profile_id = max(1,min(round(profile_id),n_profiles));
z_km_vec = out.z_vec(:).*1e-3;

switch uncertainty_range
    case "nr"
        u_plt       = out.pc_uncertainty_nr;
        u_total_plt = out.uNO3_nr(:,profile_id);
        N_plt       = out.N_o3_nr_pc(:,profile_id);
    case "fr"
        u_plt       = out.pc_uncertainty_fr;
        u_total_plt = out.uNO3_fr(:,profile_id);
        N_plt       = out.N_o3_fr_pc(:,profile_id);
    case "merged"
        u_plt       = out.pc_uncertainty_merged;
        u_total_plt = out.uNO3_pc_merged(:,profile_id);
        N_plt       = out.N_o3_pc_merged(:,profile_id);
end

pc_on_fr = out.pc_on_fr(:,profile_id);
pc_off_fr = out.pc_off_fr(:,profile_id);
pc_on_nr = out.pc_on_nr(:,profile_id);
pc_off_nr = out.pc_off_nr(:,profile_id);

% Plot component magnitudes on logarithmic axes; this is the PC subtotal.
% ? is it necessary to use the magnitude. need to understand negative values
u_profiles = abs([u_plt.DET(:,profile_id) u_plt.SAT(:,profile_id) u_plt.BKG(:,profile_id) u_plt.O3(:,profile_id) u_plt.RAYLEIGH(:,profile_id) u_total_plt]);
u_profiles(u_profiles <= 0) = NaN;

u_relative = u_profiles ./ abs(N_plt) .* 100;
u_relative(N_plt <= 0,:) = NaN;
u_mixing = u_profiles ./ out.Na(:,profile_id) .* 1e9;

figure; %[output:491030af]
set(gcf,"Position",[100 100 1000 650]); %[output:491030af]

subplot(1,2,1) %[output:491030af]
h = semilogx(u_relative,z_km_vec,"LineWidth",1.2); %[output:491030af]
h(6).LineStyle = "--"; %[output:491030af]
xlim([0.01 300]); %[output:491030af]
ylim([0 10]); %[output:491030af]
xlabel("Ozone Number Density Uncertainty (%)"); %[output:491030af]
ylabel("Altitude (km)"); %[output:491030af]
legend("Detection","Saturation","Background","Ozone cross section","Rayleigh extinction","PC subtotal","Location","best","FontSize",10); %[output:491030af]
grid on; %[output:491030af]

subplot(1,2,2) %[output:491030af]
h = semilogx(u_mixing,z_km_vec,"LineWidth",1.2); %[output:491030af]
h(6).LineStyle = "--"; %[output:491030af]
xlim([0.01 100]); %[output:491030af]
ylim([0 10]); %[output:491030af]
xlabel("Ozone Mixing Ratio Uncertainty (ppb)"); %[output:491030af]
ylabel("Altitude (km)"); %[output:491030af]
legend("Detection","Saturation","Background","Ozone cross section","Rayleigh extinction","PC subtotal","Location","best","FontSize",10); %[output:491030af]
grid on; %[output:491030af]

sgtitle(sprintf("PC %s Uncertainty | Profile %d | %s",upper(uncertainty_range),profile_id,string(out.times_avg(profile_id)))); %[output:491030af]
Na = out.Na(:,profile_id);
figure; %[output:077a1b34]

plot(1e9 .* N_plt ./ Na,z_km_vec, "LineWidth", 1.2, 'DisplayName','O_3'); %[output:077a1b34]
ylabel("Ozone Number Density (ppb)"); %[output:077a1b34]



xlim([-10 120]) %[output:077a1b34]
set(gca, "YDir", "normal"); %[output:077a1b34]
xlabel("Altitude (km)"); %[output:077a1b34]
title(sprintf("Ozone Profile | %s", string(out.times_avg(profile_id)))); %[output:077a1b34]
grid on; %[output:077a1b34]
legend %[output:077a1b34]
figure; %[output:62872c4b]
semilogy(z_km_vec,pc_on_fr, "LineWidth", 1.2, 'DisplayName','On fr'); %[output:62872c4b]
hold on %[output:62872c4b]
plot(z_km_vec,pc_off_fr, "LineWidth", 1.2, 'DisplayName','Off fr'); %[output:62872c4b]
plot(z_km_vec,pc_on_nr, "LineWidth", 1.2, 'DisplayName','On nr '); %[output:62872c4b]
plot(z_km_vec,pc_off_nr, "LineWidth", 1.2, 'DisplayName','Off nr'); %[output:62872c4b]

hold off %[output:62872c4b]
ylabel("MHz"); %[output:62872c4b]
grid on; %[output:62872c4b]
legend %[output:62872c4b]
xlim([0 5]) %[output:62872c4b]

%%\ PC merge diagnostics
n_profiles = length(out.times_avg);
merge_profile_id = 1; %[control:slider:b905]{"position":[20,21]}
merge_profile_id = max(1,min(round(merge_profile_id),n_profiles));
i = merge_profile_id;
z_km = out.z_vec(:).*1e-3;

fits = {out.pc_fit_on_fr out.pc_fit_off_fr out.pc_fit_on_nr out.pc_fit_off_nr};
ranges = {out.range_on_fr out.range_off_fr out.range_on_nr out.range_off_nr out.range_fr_nr_on out.range_fr_nr_off};
analog = {out.an_on_fr out.an_off_fr out.an_on_nr out.an_off_nr};
pc = {out.pc_on_fr out.pc_off_fr out.pc_on_nr out.pc_off_nr};
channel_names = {"FR ON" "FR OFF" "NR ON" "NR OFF"};

figure(201); clf; %[output:0b2769f3]
set(gcf,"Position",[100 100 1400 850]); %[output:0b2769f3]
for j = 1:4
    fit = fits{j};
    heights = z_km(fit.centres);
    ref = fit.reference_range(:,i);
    scaled_analog = analog{j}(:,i).*fit.reference_slope(i) + fit.reference_intercept(i);
    scaled_analog(scaled_analog <= 0) = NaN;
    limits = z_km(fit.search_range);

    subplot(2,4,j) %[output:0b2769f3]
    semilogx(pc{j}(:,i),z_km,scaled_analog,z_km,"LineWidth",1);
    hold on
    ids = [];
    if all(isfinite(ref))
        ids = ref(1):ref(2);
    end
    plot(pc{j}(ids,i),z_km(ids),"g.","MarkerSize",4);
    xline(fit.reference_rates(1),":","HandleVisibility","off");
    xline(fit.reference_rates(2),":","HandleVisibility","off");
    top = limits(2);
    if all(isfinite(ref))
        top = max(top,z_km(ref(2)));
    end
    ylim([limits(1) top]);
    xlabel("Corrected count rate (MHz)");
    ylabel("Altitude (km)");
    title(channel_names{j});
    legend("PC","Scaled analog","Reference interval","Location","southoutside","FontSize",8);
    grid on

    % A window passes when all three curves are at or below 1.
    checks = [(1-fit.r2(:,i))./(1-fit.min_r2) fit.residual(:,i)./fit.max_residual fit.slope_difference(:,i)./fit.max_slope_difference];
    subplot(2,4,j+4)
    plot(checks,heights,"LineWidth",1);
    hold on
    good = fit.valid(:,i);
    plot(zeros(sum(good),1),heights(good),"g.","MarkerSize",8);
    xline(1,"--","Limit","HandleVisibility","off");
    xlim([0 3]);
    ylim(limits);
    xlabel("Check / allowed limit");
    ylabel("Altitude (km)");
    title(sprintf("Reference R^2 %.3f | Residual %.1f%%",fit.reference_r2(i),100*fit.reference_residual(i)));
    legend("1-R^2","Residual","Slope difference","Passing windows","Location","southoutside","FontSize",8);
    grid on
end
sgtitle(sprintf("PC merge checks | Profile %d | %s",i,string(out.times_avg(i)))); %[output:0b2769f3]
figure(202); clf; %[output:453ba2e8]
set(gcf,"Position",[100 100 1150 650]); %[output:453ba2e8]
subplot(1,3,1) %[output:453ba2e8]
for j = 1:6
    selected = ranges{j}(:,i);
    if all(isfinite(selected))
        plot([j j],z_km(selected),"o-","LineWidth",3); %[output:453ba2e8]
        hold on
    end
end
xticks(1:6); %[output:453ba2e8]
xticklabels([channel_names {"FR-NR ON" "FR-NR OFF"}]); %[output:453ba2e8]
xlim([0.5 6.5]); %[output:453ba2e8]
ylim(limits); %[output:453ba2e8]
ylabel("Altitude (km)"); %[output:453ba2e8]
title("Accepted intervals"); %[output:453ba2e8]
grid on %[output:453ba2e8]

subplot(1,3,2) %[output:453ba2e8]
plot([out.q_o3_pc_nr(:,i) out.q_o3_pc_fr(:,i) out.q_o3_pc_merged(:,i) out.q_o3_an_fr(:,i)],z_km,"LineWidth",1.2); %[output:453ba2e8]
xlim([-60 120]); %[output:453ba2e8]
ylim(limits); %[output:453ba2e8]
xlabel("Ozone (ppb)"); %[output:453ba2e8]
ylabel("Altitude (km)"); %[output:453ba2e8]
legend("NR PC","FR PC","Merged PC","FR analog","Location","southoutside"); %[output:453ba2e8]
title("Retrievals"); %[output:453ba2e8]
grid on %[output:453ba2e8]

subplot(1,3,3) %[output:453ba2e8]
plot(out.w_o3_pc(:,i),z_km,"LineWidth",1.2); %[output:453ba2e8]
xlim([0 1]); %[output:453ba2e8]
ylim(limits); %[output:453ba2e8]
xlabel("NR weight"); %[output:453ba2e8]
ylabel("Altitude (km)"); %[output:453ba2e8]
title("Merge weights"); %[output:453ba2e8]
grid on %[output:453ba2e8]

if isfinite(out.start_pc_merge(i)) %[output:group:1afcdd04]
    for j = 1:3
        subplot(1,3,j) %[output:453ba2e8]
        yline(z_km(out.start_pc_merge(i)),"--","HandleVisibility","off");
        yline(z_km(out.end_pc_merge(i)),"--","HandleVisibility","off");
    end
    sgtitle(sprintf("PC merge result | Profile %d | %s",i,string(out.times_avg(i)))); %[output:453ba2e8]
else
    sgtitle(sprintf("PC merge result | Profile %d | No common accepted interval",i));
end %[output:group:1afcdd04]

figure(203); clf; %[output:46483d16]
set(gcf,"Position",[100 100 900 650]); %[output:46483d16]
linear_fits = {out.fit_fr_nr_on out.fit_fr_nr_off};
names = {"ON" "OFF"};
for j = 1:2
    fit = linear_fits{j};
    heights = z_km(fit.centres);
    checks = [(1-fit.r2(:,i))./(1-fit.min_r2) fit.residual(:,i)./fit.max_residual];
    subplot(1,2,j) %[output:46483d16]
    plot(checks,heights,"LineWidth",1.2);
    hold on
    good = fit.valid(:,i);
    plot(zeros(sum(good),1),heights(good),"g.","MarkerSize",8);
    xline(1,"--","Limit","HandleVisibility","off");
    xlim([0 3]);
    ylim(z_km(fit.search_range));
    xlabel("Check / allowed limit");
    ylabel("Altitude (km)");
    title(names{j});
    legend("1-R^2","Residual","Passing windows","Location","southoutside");
    if isfinite(out.start_pc_merge(i))
        yline(z_km(out.start_pc_merge(i)),"--","Linear merge start","HandleVisibility","off");
        yline(z_km(out.end_pc_merge(i)),"--","Linear merge end","HandleVisibility","off");
    end
    if isfinite(out.start_pc_merge_anpc(i))
        yline(z_km(out.start_pc_merge_anpc(i)),":","Analog-PC start","HandleVisibility","off");
        yline(z_km(out.end_pc_merge_anpc(i)),":","Analog-PC end","HandleVisibility","off");
    end
    grid on
end
sgtitle(sprintf("FR-NR PC linearity | Profile %d | %s",i,string(out.times_avg(i)))); %[output:46483d16]

